<script>(()=>{const dialog=document.getElementById('membershipLock'),title=dialog?.querySelector('[data-membership-lock-title]'),detail=dialog?.querySelector('[data-membership-lock-detail]');document.querySelectorAll('[data-membership-lock]').forEach(button=>button.addEventListener('click',()=>{if(title)title.textContent=button.dataset.lockTitle||title.textContent;if(detail)detail.textContent=button.dataset.lockDetail||detail.textContent;dialog?.showModal()}));document.querySelector('[data-close-membership]')?.addEventListener('click',()=>dialog?.close())})();</script>
